# owner: platform
"""Short absence notices to send home to parents."""

from datetime import date
from typing import Iterable, List

from rosterkit.attendance import days_missed
from rosterkit.models import Mark, Student

# ---
def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Plain text notice of a student's absent days."""
    missed = absent_days(student, marks)
    if not missed:
        raise ValueError("no absences to report")
    return notice_line(student, missed)

# ---
def absent_days(
    student: Student, marks: Iterable[Mark]
) -> List[date]:
    """Absent days for one student, oldest first."""
    own_marks = list(marks)
    check_same_student(student, own_marks)
    return days_missed(own_marks)

# ---
def check_same_student(
    student: Student, marks: List[Mark]
) -> None:
    """Raise when a mark belongs to someone else."""
    others = {mark.student_id for mark in marks}
    found = others - {student.student_id}
    if found:
        raise ValueError(f"other students: {sorted(found)}")

# ---
def notice_line(
    student: Student, missed: List[date]
) -> str:
    name = f"{student.first_name} {student.last_name}"
    count = len(missed)
    noun = "day" if count == 1 else "days"
    dates = "; ".join(format_day(item) for item in missed)
    return f"{name} was absent {count} {noun}: {dates}."

# ---
def format_day(when: date) -> str:
    """Spell a date out, e.g. September 1, 2026."""
    return f"{when:%B} {when.day}, {when.year}"
